// Engine demo for layered painted environments (quality plan point 2, 4 Nov 2026; assets/environments/README.md):
// Phoenix and Reaper (sheet look) walk down the painted meadow road, stop, and take in the view. It shows the
// multiplane parallax on a camera move, the cast walking and casting shadows on the painted ground, the grass and
// leaves swaying, and a cut to a closer shot inside the safe camera range. Pure engine test: no creative review.
//   node storyboards/env/make-meadow-demo.mjs
//   node qa/env.mjs storyboards/env/meadow-demo.json && node engine/render.mjs storyboards/env/meadow-demo.json
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { clip } from "../lib/clip.mjs";

const OUT = path.dirname(fileURLToPath(import.meta.url));
const ENV = process.argv[2] || "meadow-path";
const E = JSON.parse(fs.readFileSync(path.join(OUT, "../../assets/environments", ENV, "env.json"), "utf8"));
const [ex, ey, ez] = E.eye.pos;

const c = clip(), { A, cap } = c, END = 9.0;
// places: the road runs away from the painting camera (its middle drifts right with distance: x 0.2-0.5 m at 6-9 m);
// the pair walk toward us on it, a body-width apart
const PHX0 = [-0.12, -3.9], REA0 = [0.84, -4.9], PHX1 = [-0.3, -1.5], REA1 = [0.62, -2.4];   // Reaper a step behind

// 1 WALK 0-4.6: already walking at frame 0, the camera trucks slowly to the right (near banks slide past far hills)
A(0, "phx", "noblink"); A(0, "rea", "noblink");
A(0, "phx", "move", { to: PHX1, dur: 3.6, steps: 2.2 });
A(0.08, "rea", "move", { to: REA1, dur: 3.5, steps: 2.0 });
A(1.2, "rea", "look", { to: [-0.6, 0.1], dur: 0.25 });          // a glance at Phoenix
A(2.0, "rea", "look", { to: [0, 0.05], dur: 0.3 });
A(2.4, "phx", "look", { to: [0.5, 0.45], dur: 0.3 });           // the sky catches Phoenix's eye
// 2 STOP + LOOK 3.6-6.4: they stop; Phoenix turns to the view and points up at the clouds, Reaper follows his look
A(3.75, "phx", "turn", { to: "3q-right", dur: 0.4 });
A(4.0, "phx", "arm", { side: "R", pose: "up", dur: 0.4 });
A(4.1, "phx", "expr", { expr: "happy", dur: 0.25 });
A(4.15, "rea", "look", { to: [-0.4, 0.6], dur: 0.3 });
A(4.6, "rea", "expr", { expr: "kind", dur: 0.3 });
A(5.6, "phx", "arm", { side: "R", pose: "rest", dur: 0.45 });
// 3 BACK TO US 6.4-9.0: both turn to the camera, Reaper's small smile
A(6.2, "phx", "turn", { to: "camera", dur: 0.4 });
A(6.3, "rea", "look", { to: [0, 0], dur: 0.3 });
A(6.6, "phx", "look", { to: [0, 0], dur: 0.25 });
A(7.0, "rea", "expr", { expr: "happy", dur: 0.3 });
cap(0, 2.4, "layered painted environment", 300, false, { kinetic: false });

// shots (inside qa/env.mjs --range of the env): a wide truck, then a closer, lower two-shot
// the painting camera looks along its own axis (env.json eye.pitch: + down); the wide shot keeps that view
const p = (E.eye.pitch * Math.PI) / 180, ahead = (pos, k = 10) => [pos[0], pos[1] - Math.sin(p) * k, pos[2] - Math.cos(p) * k];
const W0 = [ex - 0.3, ey, ez + 0.15], W1 = [ex + 0.3, ey, ez];
const WIDE = { pos: W0, look: ahead(W0), fov: 36, to: { pos: W1, look: ahead(W1) }, dur: 3.9, ease: "inOut" };
const C0 = [0.32, 0.86, 2.7], C1 = [0.22, 0.86, 2.45];
const CLOSE = { pos: C0, look: [0.03, 0.8, -1.6], fov: 38, to: { pos: C1, look: [0.03, 0.82, -1.6] }, dur: 5.1, ease: "inOut" };

const sb = {
  id: "meadow-demo", title: "Layered painted environment: meadow road (engine demo)",
  idea: "Engine demo, not a clip: point 2 of the quality plan",
  fps: 30, look: "anime-pro", castLook: "sheet", profile: "short", loop: false, motion: "natural",
  set: { type: "env", env: ENV, shade: "soft", aperture: 0, focus: false },
  drawn: { lines: { width: 5.4, pressure: 1.2, taper: 0.85, tint: 0.4 }, brush: { glow: 0, wrap: 0.12, cool: 0.2 }, paint: { edge: 0.35 }, paper: { grain: 0.12, wash: 0.09, pool: 0.15 } },
  music: { style: "lofi", seed: 41 }, sound: { sfx: 0.7, ambience: 0.5 },
  creative: { length: [6, 20], notes: false },
  hook: { show: ["phx", "rea"], hint: 0, what: "engine demo" },
  cast: [
    { id: "phx", character: "duo/phoenix", at: PHX0, face: "camera", expr: "kind", follow: 0.3, seed: 1.7, span: 0 },
    { id: "rea", character: "lookdev/reaper-crisp", at: REA0, face: "camera", expr: "kind", follow: 0.3, seed: 2.2 },
  ],
  props: [],
  beats: c.beats([["walk", 0, WIDE], ["view", 3.9, CLOSE]], END),
  duration: END,
  notes: "Generated by storyboards/env/make-meadow-demo.mjs (engine demo).",
};
fs.writeFileSync(path.join(OUT, "meadow-demo.json"), JSON.stringify(sb, null, 1) + "\n");
console.log("wrote storyboards/env/meadow-demo.json");
